void DFS( int num , int vis [2001] , int * count){
	vis[num] = 1 ;
	(*count) ++ ;
	int i = 1 ;
	for(; i <= n ; i++){
		if(arr[num][i] && !vis[i]){
			vis[i] = 1 ;
			DFS(i , vis, count) ;
		}
	}
}

void iDFS( int num , int vis [2001] , int * count){
	vis[num] = 1 ;
	(*count) ++ ;
	int i = 1 ;
	for(; i <= n ; i++){
		if(arr[i][num] && !vis[i]){
			vis[i] = 1 ;
			iDFS(i , vis, count) ;
		}
	}
}

