    int x,y;
    scanf("%d%d",&x,&y);
    visited[1][x][y]=1;
    if (tap[1][x][y]=='.')
    dfs(1,x,y);
    printf("%d",ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
     int a;
     int b;
     int c;
} employee;

int cmp(const void *a, const void *b)
{
     return ((employee *)a)->c - ((employee *)b)->c;
}

int main(int argc, char *argv[])
{
     int n, m, sum = 0, f = 0, i;
     int q[1000], a[1000] = {0};
     employee e[10000];

     scanf("%d", &n);

     for (i = 0; i < n; i++) scanf("%d", &q[i]);

     scanf("%d", &m);

     for (i = 0; i < m; i++) scanf("%d %d %d", &e[i].a, &e[i].b, &e[i].c);

     if (n == 1) {
	  puts("0");

	  return 0;
     }

     qsort(e, m, sizeof(employee), cmp);

     for (i = 0; i < m; i++) {
	  if (q[e[i].a - 1] <= q[e[i].b - 1]) continue;

	  if (a[e[i].b - 1] != 1) {
	       if (a[e[i].a - 1] == 0) {
		    a[e[i].a - 1] = 2;
		    a[e[i].b - 1] = 1;

		    sum += e[i].c;
	       } else {
		    a[e[i].b - 1] = 1;

		    sum += e[i].c;
	       }
	  }
     }

     for (i = 0; i < n; i++) {
	  if (a[i] == 0) {
	       puts("-1");

	       return 0;
	  } else if (a[i] == 2) {
	       f++;
	  }
     }

     if (f > 1) {
	  puts("-1");
     } else {
	  printf("%d\n", sum);
     }

     return 0;
}

#include <stdio.h>
#include <ctype.h>

#define SIZE 55
#define MOD 1000000007

typedef struct {
	unsigned long long int m[SIZE][SIZE];
} mat;

int m;
mat valid;

mat multiply(mat A, mat B){
	int i, j, k;
	mat C;
	for (i = 0; i < m; i++)
		for (j = 0; C.m[i][j] = 0, j < m; j++)
			for (k = 0; k < m; k++)
				C.m[i][j] = (C.m[i][j] + A.m[i][k] * B.m[k][j]) % MOD;
	return C;
}

mat matexp(unsigned long long int p){
	int i, j, k;
	mat ans;

	if (p == 0){
		for (i = 0; i < m; i++)
			for (j = 0; j < m; j++)
				ans.m[i][j] = i == j;
	} else if (p == 1){
		return valid;
	} else if (p % 2 == 0){
		ans = matexp(p/2);
		ans = multiply(ans, ans);
	} else {
		ans = matexp(p/2);
		ans = multiply(multiply(ans, ans), valid);
	}

	return ans;
}

int main(int argc, char *argv[]){
	int i, j, a, b, k;
