#include <stdio.h>

int x[200000], y[200000];

void sort(int l, int r) {
	if (l < r) {
		int i = l, j = r, m = (l + r) / 2, px = x[m], py = y[m];
		while (i <= j)
			if (x[i] < px || x[i] == px && y[i] < py)
				i++;
			else if (px < x[j] || px == x[j] && py < y[j])
				j--;
			else {
				int t = x[i]; x[i] = x[j]; x[j] = t;
				t = y[i]; y[i] = y[j]; y[j] = t;
				i++; j--;
			}

		sort(l, j); sort(i, r);
	}
}

