long long power(long long b,long long e)
{
        if(e==1)
        return b;
        long long k=power(b,e/2);
        k=(k*k)%M;
        if(e%2)
        k=(k*b)%M;
        return k;
}
long long getinverse(long long i)
{
        return power(i,M-2)%M;
}
