int n, a[5050][5050], act[5050][5050];
int timer = 1;
int foundCycle = 0;
char vis[5050];
int cycle[5050], cycleCnt, ctin[5050];
int tin[5050];

void dfs(int v) {
    if(foundCycle)
        return;
    tin[v] = timer++;
    vis[v] = 1;
    int i, j;
    for(i = 0; !foundCycle && i < n; i++) {
        if(!a[v][i] || vis[i] == 2)
            continue;
        if(vis[i] == 0) {
            dfs(i);
        } else if(vis[i] == 1) {
            foundCycle = 1;
            for(j = 0; j < n; j++) {
                if(vis[j] == 1) {
                    cycle[cycleCnt] = j;
                    ctin[cycleCnt] = tin[j];
                    cycleCnt++;
                }
            }
            return;
        }
    }
    vis[v] = 2;
}

void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

