        puts("-1");
    else {
        for(i = 0; i < cycleCnt; i++) {
            for(j = i + 1; j < cycleCnt; j++) {
                if(ctin[j] < ctin[i]) {
                    swap(&ctin[i], &ctin[j]);
                    swap(&cycle[i], &cycle[j]);
                }
            }
        }
        cycle[cycleCnt] = cycle[0];
