void calc(int x, int y)
{
    if(x==0||y==0||y==n+1||x==m+1) return;
    if(a[y][x] == '*') {
	++sum;
	return;
    }
    if(visited[y][x] != 0) return;
    visited[y][x] = compo_count;
    calc(x + 1, y);
    calc(x, y - 1);
    calc(x - 1, y);
    calc(x, y + 1);
}



