	Matrix_t A;
	for(i=0;i<4;++i)
	{
		for(j=0;j<4;++j)
		{
			A.data[i][j]=i==j?0:1;
		}
	}
	scanf("%d",&N);
	printf("%d\n",ModExp(A,N));
	return 0;
}

