#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef char* element;

typedef struct node
{
  element data;
  int to_add;
  struct node *left;
  struct node *right;
  struct node *parent;
}one_node;

typedef one_node *tree_t;

void make_null_tree(tree_t *tree)
{
  *tree = NULL;
}

tree_t create_node(element value)
{
  one_node *new = (one_node*) malloc (sizeof(one_node));
  if(new == NULL)
    return NULL;

  new->data = value;
  new->to_add = 1;
  new->left = new->right = new->parent = NULL;
  return new;
}

void out_put (tree_t tree)
{
  tree_t current;
  current = tree;
  printf ("%s", current->data);

  if (strcmp (current->data, "pair") == 0)
    {      
      printf ("<");
      out_put (current->left);
      printf (",");
      out_put (current->right);
      printf (">");
    }
}

