char *arab2roman(long long arab) {
        static char roman[100];
        const int m = sizeof(arabar)/sizeof(int)-1, arabmax=arabar[m];
        const char romanmax=romanar[m][0];
        int i, n;
        if(!arab) {
                *roman=0;
                return roman;
        }
        i=0;
        while(arab>arabmax) {
                roman[i++] = romanmax;
                arab      -= arabmax;
        }
        n=m;
        while(arab > 0) {
                if(arab >= arabar[n]) {
                        roman[i++] = romanar[n][0];
                        if(n&1)
                                roman[i++] = romanar[n][1];
                        arab -= arabar[n];
                } else
                        n--;
        }
        roman[i]=0;
        return roman;
}


