            {
                maxSum = max(maxSum, temp*flag);
                temp = a[i]; flag = 1; continue;
            }
            else
            {
                temp = a[i]; flag = 1;
            }
        }
    }
    if (flag>1)
    {
        maxSum = max(maxSum, temp*flag);
    }

    int results;
