	for(i=1;i<=N;i++){
		scanf("%c",&s[i]);
		if(s[i]=='a'){
			a[i]=a[i-1]+1;
			b[i]=b[i-1];
		}
		else{
			a[i]=a[i-1];
			b[i]=b[i-1]+1;
		}
	}
