int dfs(int x, int y, int z)
{
    int p, q, i, j;

    if (x == n && y == 0) return 1;

    p = x;
    q = y + 1;

    if (q == n) {
        p = x + 1;
        q = 0;
    }

    for (i = 0; i < n * n; i++) {
        if ((z >> i) & 1) continue;

        if (x == n - 1) {
            int s = 0;

            for (j = 0; j < n - 1; j++) s += b[j][y];

            if (s + a[i] != sum) continue;
        }

        if (y == n - 1) {
            int s = 0;

            for (j = 0; j < n - 1; j++) s += b[x][j];

            if (s + a[i] != sum) continue;
        }

        if (x == n - 1 && y == 0) {
            int s = 0;

            for (j = 0; j < n - 1; j++) s += b[j][n - j - 1];

            if (s + a[i] != sum) continue;
        }

        if (x == n - 1 && y == n - 1) {
            int s = 0;

            for (j = 0; j < n - 1; j++) s += b[j][j];

            if (s + a[i] != sum) continue;
        }

        b[x][y] = a[i];

        if (dfs(p, q, z | (1 << i)) == 1) return 1;

        for (j = i + 1; j < n * n; j++) {
            if (a[i] != a[j]) break;
        }

        i = j - 1;
    }

    return -1;
}

int dfs2(int p, int q)
{
    int x, y, i, j;

    if (p <= 3) {
        x = 0;
        y = p;
    } else if (p <= 6) {
        x = p - 3;
        y = 0;
    } else if (p <= 9) {
        x = 1;
        y = p - 6;
    } else if (p <= 11) {
        x = p - 8;
        y = 1;
    } else if (p <= 13) {
        x = 2;
        y = p - 10;
    } else {
        x = 3;
        y = p - 12;
    }

    for (i = 0; i < n * n; i++) {
        if ((q >> i) & 1) continue;

        if (x == n - 1) {
            int s = 0;

            for (j = 0; j < n - 1; j++) s += b[j][y];

            if (s + a[i] != sum) continue;
        }

        if (y == n - 1) {
            int s = 0;

            for (j = 0; j < n - 1; j++) s += b[x][j];

            if (s + a[i] != sum) continue;
        }

        if (p == 10) {
            int s = 0;

            for (j = 0; j < n; j++) {
                if (j == 2) continue;

                s += b[j][n - j - 1];
            }

            if (s + a[i] != sum) continue;
        }

        if (x == n - 1 && y == n - 1) {
            int s = 0;

            for (j = 0; j < n - 1; j++) s += b[j][j];

            if (s + a[i] != sum) continue;
        }

        b[x][y] = a[i];

        if (dfs2(p + 1, q | (1 << i)) == 1) return 1;

        for (j = i + 1; j < n * n; j++) {
            if (a[i] != a[j]) break;
        }

        i = j - 1;
    }

    return -1;
}

