int d[2][300][300];

void swapd()
{
    int i, j;
    for(i = 0; i < n; i++)
    {
        for(j = 0; j < n; j++)
        {
            d[0][i][j] = d[1][i][j];
            d[1][i][j] = -1000000;
        }
    }
}

void add(int i, int j, int di, int dj, int u, int dw, int s)
{
    int ans = 0;
    if(di >= dw && di <= u && dj >= dw && dj <= u)
    {
        ans = d[0][i][j];
        ans += f[s - di][di];
        if(di != dj)
        {
            ans += f[s - dj][dj];
        }
        if(ans > d[1][di][dj])
        {
            d[1][di][dj] = ans;
        }
    }
}

