		for(i = 0; i < b; i++)
		{
			scanf("%d", &k);
			d[k] = 1;
		}
		if(m > n)
		{
			k = GY(m, n);
			t = m - n;
		}
		else
		{
			k = GY(n, m);
			t = n - m;
		}
		if(k > t)
			k = GY(k, t);
		else
			k = GY(t, k);
		y = 1;
		for(i = 0; i < k; i++)
		{
			x = 0;
