#include<stdio.h>
typedef int64_t lld;
lld mod(lld a, lld b, lld m)
{
    lld ret=1;
    a%=m;
    while(b)
    {
        if(b&1)ret=ret*a%m;
        b>>=1;
        a=a*a%m;
        //printf("b=%lld\n",b);
    }
    return ret;
}

