int go(int i)
{
    int j=i;
    i--;
    for(i;x[i]==49||x[i]==48;i--)
    {
        if(x[i]=='0')
        {
            x[i]='1';
            return 1;
        }
        else
            x[i]='0';
    }
    return j-i;
}

