}

#include "stdio.h"
#include "stdlib.h"

int n,t[100000];

void QSort(int l, int r)
{
	int p=l,q=r,z=t[l+rand()%(r-l+1)],temp;
	while (p<q)
	{
		while (t[p]<z) p++;
		while (z<t[q]) q--;
		if (p<=q)
		{
			temp=t[p];
			t[p++]=t[q];
			t[q--]=temp;
		}
	}
	if (l<q)
		QSort(l,q);
	if (p<r)
		QSort(p,r);
}

