#include <stdio.h>

int win(char player, char board[][3]) {
	int i, j;

	for (i = 0; i < 3; i++)
		if (board[i][0] == player
				&& board[i][1] == player
				&& board[i][2] == player)
			return 1;
	for (j = 0; j < 3; j++)
		if (board[0][j] == player
				&& board[1][j] == player
				&& board[2][j] == player)
			return 1;

	if (board[0][0] == player
			&& board[1][1] == player
			&& board[2][2] == player)
		return 1;
	if (board[0][2] == player
			&& board[1][1] == player
			&& board[2][0] == player)
		return 1;
	return 0;
}

