#include <stdio.h>

int binary(int l, int r, int target, int arr[])
{
    if ( l > r )
        return -1;
    int middle = (l+r)>>1;
    if ( arr[middle] == target )
        return middle;
    else if ( arr[middle] > target )
        return binary(l, middle-1, target, arr);
    else
        return binary(middle+1, r, target, arr);
}

