                    return 1;
                }
                if(!Visit[newX][newY] && Map[newX][newY] == '.') {
                    Visit[newX][newY] = 1;
                    Queue[Tail][0] = newX;
                    Queue[Tail++][1] = newY;
                }
            }
        }
        ++Head;
    }
    return 0;
}

