int che[1000010];
void mergesort(int arr[],int t)
{
	if(t<=1)
		return;
	mergesort(arr,t/2);
	mergesort(&arr[t/2],t-t/2);
	int i=0,j=t/2,k=0;
	while(i<t)
	{
		if(j==t)
		{
			che[i]=arr[k];
			k++;
		}
		else if(k==t/2 || arr[k]>arr[j])
		{
			che[i]=arr[j];
			j++;
		}
		else 
		{
			che[i]=arr[k];
			k++;
		}
		i++;
	}
	i=0;
	while(i<t)
	{
		arr[i]=che[i];
		i++;
	}
}
