char temp[10005];

void rotate(char *input, int l, int r, int k) {
    int length = r - l + 1;
    int steps = k % length;
    if (steps) {
        steps = length - steps;
        int f = l - 1;
        int s = f + steps;
        char *first = &input[f];
        int l1 = steps;
        char *second = &input[s];
        int l2 = length - steps;
        strncpy(temp, second, l2);
        strncpy(&temp[l2], first, l1);
        strncpy(&input[f], temp, length);
    }
}

