void merge(int a[],int l,int m,int r)
{
    int b[r+1];
    int h=l,i=l,j=m+1;
    while((h<=m) && (j<=r))
    {
        if(a[h]<=a[j])
        {
            b[i]=a[h];
            h++;
        }
        else
        {
            b[i]=a[j];
            j++;
        }
        i++;
    }
    int k=0;
    if(h>m)
    {
        for(k=j;k<=r;k++)
        {
            b[i]=a[k];
            i++;
        }
    }
    else
    {
        for(k=h;k<=m;k++)
        {
            b[i]=a[k];
            i++;
        }
    }
    for(k=l;k<=r;k++)
    {
        a[k]=b[k];
    }
}
void mergesort(int a[],int l,int r)
{
    if(l<r)
    {
        int m=floor(l+(r-l)/2);
        mergesort(a,l,m);
        mergesort(a,m+1,r);
        merge(a,l,m,r);
    }
}
