unsigned long long combinaison (short n, short m){
    int i;
    unsigned long long c=1;
    short aux=n;
    if (n<m) return 0;
    else{
        if (!(n==0 && m==0)){
            for (i=1;i<=m;i++){
                c*=aux;
                c/=i;
                aux--;
            }
        }
        return c;
    }
}

