long int interval(long int t)
{
    long int p=0;
    if (t<=t1) return t*p1;
    else {
        p+=t1*p1;
        t=t-t1;
        if (t<=t2) {p+=t*p2; return p;}
        else {
            p+=t2*p2+(t-t2)*p3;
            return p;
        }
    }
}

