int make_k_bonacci(int k){
    int i,j;
    memo[k] = 1;
    for(i=k+1;;i++){
        for(j=1;j<=k;j++){
            memo[i] += memo[i-j];
            if(memo[i]<0) return i;
        }
    }
}

