void z_algo(){
    int lf=0,rt=0,i,k,ip;/*lf,rt記錄現在檢查過最右邊的區間*/
    z[0]=sz;
    for(i=1;i<sz;i++){
        if(i>rt){ /*i不在[lf,rt] 需要從頭比對*/
            for(k=0;i+k<sz&&pat[k]==pat[i+k];k++);
            z[i]=k;
            lf=i;
            rt=i+k-1;
        }
        else{ /*i在[lf,rt] 可將i映射至ip*/
            ip=i-lf;
            if(i+z[ip]>rt){
                for(k=rt-i+1;i+k<sz&&pat[k]==pat[i+k];k++);
                z[i]=k;
                lf=i;
                rt=i+k-1;
            }
            else z[i]=z[ip];
        }
    }
}

