int rowmax(int arr[][505], int row, int m)
{
        int count = 0, mx = 0, i, j;
        int flag = 0;

        for(i = 1; i<= m; i++){
                if(flag == 0 && arr[row][i] == 1){
                        count = 1;
                        flag = 1;
                } else if(flag == 1 && arr[row][i] == 1){
                        count++;
                } else if(arr[row][i] == 0){
                        flag = 0;
                        count = 0;
                }
                if(count > mx){
                        mx = count;
                }
        }

        return mx;
}


