ll nto10(char s[],int n)
{
  int i,j;
  ll res=0,p=1;
  for(i=strlen(s)-1;i>=0;i--){
    for(j=0;j<n;j++){
      if(s[i]==t[j]){
        res+=T[j]*p;
        break;
      }
    }
    p*=n;
  }
  return res;
}
void swap(char*a,char*b){char t=*a;*a=*b;*b=t;}
void reverse(char*s)
{
  int i=0,j=strlen(s)-1;
  for(;i<j;i++,j--)swap(s+i,s+j);
}
