  s[c]='\0';
  reverse(s);
}
typedef struct radix {
  ll  digit;
  char roman;
  char romanNext;
} RADIX; 
char* roman(ll num, char buff[]){
  static RADIX table[4]={
    {1000,'M','*'},
    {100,'C','D'},
    {10,'X','L'},
    {1,'I','V'}
  };
  ll tableSize = sizeof(table)/sizeof(RADIX);
  ll i, j, n;
  char *p=buff;
  for(i=0;i<4;i++){
    n = num / table[i].digit;
    //printf("%lld %lld\n",n,num);
    if( 1 <= n && n <=3 ){
      for(j=0;j<n;j++)
        *p++=table[i].roman;
    } else if(n == 4){
      *p++=table[i].roman;
      *p++=table[i].romanNext;
    } else if(n == 5){
      *p++=table[i].romanNext;
    } else if(6<= n && n <=8){
      *p++=table[i].romanNext;
      for(j=0;j<n-5;j++)
        *p++=table[i].roman;
    } else if(n == 9){
      *p++=table[i].roman;
      *p++=table[i-1].roman;
    }
    //num -= n * table[i].digit;
    //if(i==3){exit(0);}
    num%=table[i].digit;
  }
  *p='\0';
  return buff;
}
