int CmpSeq(seq *s1, seq *s2,int eqc)
{
    int c;
    int n;

    if( s1->n < s2->n) n = s1->n;
    else n = s2->n;

    for( c = 0; c < n; c++ )
    {

     if( s1->arr[c] > s2->arr[c]) return 1;
     if( s1->arr[c] < s2->arr[c]) return -1;

    }
    return eqc;
}



