#include <stdio.h>

int *visited; 

int *length;

int *reds;

int totalreds;

typedef struct node
{
    int a;
    struct node* next;
} link;

void insert(link* head, int i)
{
    link* temp;
    temp = (link*)malloc(sizeof(link));
    temp->a = i;

    link* t;
    t = head->next;
    head->next = temp;
    temp->next = t;
} 

void printlist(link* head)
{
    while(head!=NULL)
    {
        printf("%d ",head->a);
        head = head->next;
    }
    printf("\n");
}

void dfs(link** red,link** green,int index)
{
    visited[index] = 1;
    link* temp;
    temp = red[index];
    temp = temp->next;

    while(temp!=NULL)
    {
        if(visited[temp->a]==0)
        {
            length[temp->a] = length[index] + 1;
            reds[temp->a] = reds[index];
            dfs(red,green,temp->a);
        }
        temp = temp->next;
    }

    temp = green[index];
    temp = temp->next;

    while(temp!=NULL)
    {
        if(visited[temp->a] == 0)
        {
            length[temp->a] = length[index] + 1;
            reds[temp->a] = reds[index] + 1;
            totalreds++;
            dfs(red,green,temp->a);
        }
        temp = temp->next;
    }
    return;
}

