#include<stdio.h>
int qsort(int *a,int low,int high)
{
    if(low>=high)
    return 0;
    int pivot=a[low],i=low+1,j=high,temp,x=1;
    while(x)
    {   while(i<=high&&a[i]<pivot)
        {   i++;
        }
        while(j>low&&a[j]>pivot)
        {   --j;
        }
        if(i>=j)
        {   x=0;
        }
        else
        {   temp=a[i];
            a[i]=a[j];
            a[j]=temp;
            ++i;
            --j;
        }
   }
   if(low<j)
   {    temp=a[low];
        a[low]=a[j];
        a[j]=temp;
   }
   qsort(a,low,j-1);
   qsort(a,j+1,high);
}
