int orig[100005],tar[100005];
int count=0;
int ans[100005];

void swap(int src)
{
	if(orig[src]==0)
		orig[src]=1;
	else 
		orig[src]=0;
}

void change_dfs(int src,int level)
{
	if(level%2==0)
	{
		if(orig[src]!=tar[src])
			swap(src);
		else
		{
		//	if(src==10)
		//		printf("ten is here.\n");
			ans[count]=src;
			count++;
			return;
		}
	}
	node * temp=head[src];
	while(temp!=NULL)
	{
		if(status[temp->data]==0)
		{
			status[temp->data]=2;
			change_dfs(temp->data,level+1);
			status[temp->data]=0;
		}
		temp=temp->next;
	}
}


void dfs(int src)
{
//	if(src==7)
//		printf("seven is here\n");
	if(orig[src]!=tar[src])
	{
		ans[count]=src;
		count++;
	//	swap(src);
		change_dfs(src,0);
	}

	node*temp=head[src];
	while(temp!=NULL)
	{
		if(status[temp->data]!=1)
		{
			status[temp->data]=1;
			dfs(temp->data);
		}
		temp=temp->next;
	}
}

