void uniqueall(int end1,int end2,int list1[])
{
    int i;
    for(i=1;i<=end1;i++)
     list1[i]=a[i];
    for(i=end2;i<=n;i++)
     list1[end1+i-end2+1]=a[i];
}
void qsort(int i,int j,int st[])
{
    int n,m,k;
    n=i,m=j,k=st[i];
    while(i<j)
    {
        while(i<j&&k<=st[j]) j--;
        if(i<j) st[i++]=st[j];
        while(i<j&&k>=st[i]) i++;
        if(i<j) st[j--]=st[i];
    }
    st[i]=k;
    if(i-n>1) qsort(n,i-1,st);
    if(m-i>1) qsort(i+1,m,st);
}
