        ib = (ib + 1) % n;

    while (A[ia] != B[ib])
        ia = (ia + 1) % n;

    int i;
    for(i = 1; i < n; i++){
        ia = (ia + 1) % n;
        ib = (ib + 1) % n;

        if (!A[ia])
            ia = (ia + 1) % n;
        if (!B[ib])
            ib = (ib + 1) % n;

        if (A[ia] != B[ib])
            return 0;
    }

    return 1;
}

