  {
   b[j]=a[i/2+y];
   j++;
   y++;
   continue;
  }
  if(y==(i-i/2))
  {
   b[j]=a[x];
   j++;
   x++;
   continue;
  }

  if(a[x].c<=a[i/2+y].c)
  {
   b[j]=a[x];
   j++;
   x++;
  }

  else
  {
