    for( i = 0; i < m; i++ )
    {
        getchar();

        for( j = 0; j < n; j++ )
        {
            scanf( "%c", &pass[i].attempt[j] );
        }

        scanf( "%hi", &pass[i].response );
    }

    k  = pass[0].response;
    taken = 0;
    rest = 0;

    combination( 0 );

    printf( "%d\n", rest );

    return 0;
}

