int gcd( int a, int b){
    int large, small, temp;

    large = small = a;
    if(a >= b) small = b;
    else large = b;

    do{
        large = large - small;
        if( large < small){
            temp = large;
            large = small;
            small = temp;
        }

    }while(large != small);
    return large;
}

