#include <stdio.h>
#include <stdlib.h>

struct matchbox
{
    int a;
    int b;
} c[20];

int cmp(const void *x, const void *y)
{
    struct matchbox *p = (struct matchbox *)x;
    struct matchbox *q = (struct matchbox *)y;
    return q->b - p->b;
}

void func(int n, int m)
{
    int ans = 0, i = 0;
    qsort(c, m, sizeof(struct matchbox), cmp);
    while (n > 0 && i < m)   // i < m, rather careless.
    {
        if (n >= c[i].a)
        {
            n -= c[i].a;
            ans += c[i].a * c[i].b;
        }
        else
        {
            ans += n * c[i].b;
            n = 0;
        }
        i ++;
    }
    printf("%d\n", ans);
}

