{
    int n, m, i;
    while (scanf("%d%d", &n, &m) == 2)
    {
        for (i = 0; i < m; i ++)
        {
            scanf("%d%d", &c[i].a, &c[i].b);
        }
        func(n, m);
    }
    return 0;
}

