long long ncr(long long n,long long r)
{
	if(r>(n-r))
		r=n-r;
	long long i,ret1=1,ret2=1,ret,j;
	int div[20]={0};
	div[1]=1;
	div[0]=1;
	for(i=0;i<r;i++)
	{
		ret1*=(n-i);
		for(j=2;j<=r;j++)
		{
			if(!(ret1%j) && !div[j])
				{
					ret1/=j;
					div[j]=1;
				}
		}
	}
	for(i=1;i<r;i++)
		if(!div[i])
			ret2*=(i+1);
	ret=ret1/ret2;
	//printf("%lld\n",ret);
	return ret;
}
