long long int ans=0;
void compute(char cmd,long long int n,long long int h,long long int power)
{
	if(h==0)
		return ;
	long long int l=power;
	long long int m=l/2;
	if(cmd=='L' && n>m)
	{
		ans=ans+l;
		long long int o=n%m;
		if(o==0)
			o=m;

		compute('L',o,h-1,l/2);
	}
	else if(cmd=='L' && n<=m)
	{
		ans=ans+1;
		compute('R',n,h-1,l/2);
	}
	else if(cmd=='R' && n<=m)
	{
		ans=ans+l;
		compute('R',n,h-1,l/2);
	}
	else if(cmd=='R' && n>m)
	{

		long long int o=n%m;
		if(o==0)
			o=m;
		ans=ans+1;
		compute('L',o,h-1,l/2);
	}

}		
