void quicksort(double x[], int first, int last)
{
	 int pivot, j, i;
	 double temp;	
     if(first<last){
	     pivot=first;
	     i=first;
	     j=last;
         while(i<j){
             while(x[i]>=x[pivot] && i<last)
                i++;
             while(x[j]<x[pivot])
                j--;
             if(i<j){
                 temp=x[i];
                 x[i]=x[j];
                 x[j]=temp;
             }
         }
         temp=x[pivot];
         x[pivot]=x[j];
         x[j]=temp;
         quicksort(x,first,j-1);
         quicksort(x,j+1,last);
   }
}

double prob(double p[], int range)
{
	int com = 1;
	double ans = 0;
	double tmp = 0;
	int i, j;

	for(i = 0; i < range; i++){
		tmp = p[i];
		for(j = 0; j < range; j++){
			if(i != j)
				tmp *= com - p[j];
		}
		ans += tmp;
	}

	return ans;
}

