    {
        if(i==dim-1 ||(vect[i]<menor && vect[i+1]>vect[i]))
        {
            menor=vect[i];
            aux1[posmen] = vect[i];
            aux2[posmen] = i;
            --posmen;
            resul[i]=-1;
        }
        else
        {
            if(vect[i]>mayor)
            {
                resul[i]=posmay-i-1;
            }
            else if(vect[i]>menor)
            {
                r=busquedaBin(aux1,aux2,posmen+1,dim,vect[i]);
                resul[i]=r-i-1;
            }
            else
            {
                resul[i]=-1;
            }
        }

    }
    for(i=0;i<dim;i++)
        {
            printf("%d ",resul[i]);
        }
