int busquedaBin(int lista[],int aux[],int inicio,int fin, int clave)
{
    int central, bajo, alto, valorCentral;
    bajo = inicio;
    alto = fin;
    while (bajo <= alto)
    {
        central = (bajo + alto)/2;
        valorCentral = lista[central];
        if (lista[central] < clave && lista[central+1] >= clave)
            return aux[central];
        else if (lista[central] < clave)
            bajo = central + 1;
        else if(lista[central] >= clave)
            alto = central - 1;
    }
    return -1;
}

