    ans[idx][(*cnt) ++] = cur + 1;
    if ((*cnt) > 3)
    {
    return;
    }
    for (i = 0; i < c[cur]; i ++)
    {
    if (v[g[cur][i]] == 0)
    {
        recur(g[cur][i], idx, cnt);
        if ((*cnt) > 3)
