void F(int n, long long k, int inc){
    if (n == 1) printf("%d ", 1 + inc);
    if (n == 2){
        if (k == 1) printf("%d %d ", 1 + inc, 2 + inc);
        else printf("%d %d ", 2 + inc, 1 + inc);
    }
    if (n < 3) return;

    if (k <= fib[n - 1]){
        printf("%d ", 1 + inc);
