int get_min(int n, int index , int sum , int *min){
    if(index == 0){
         flag = 1;
         return 0;
    }
    if(sum == 0 || sum > 9*index) return 0;
    int i = (index == n)? 1:0;
    for(i;i<=9;i++){
          if(sum - i <= 9*(index-1)){
            min[index-1] = i;
            get_min(n,index-1,sum-i,min);
            break;
          }
    }
    return 0;
}
int get_max(int n, int index , int sum , int *max){
    if(index == 0){
         flag = 1;
         return 0;
    }
    int i = 9;
    for(i;i>=0;i--){
          if(sum >= i && sum - i <= 9*(index-1)){
            max[index-1] = i;
            get_max(n,index-1,sum-i,max);
            break;
          }
    }
    return 0;
