typedef struct node {
    long value;
    long pgcd;
    struct node* next;
} node_t;

long pgcd(long a, long b){
    if(a < b) pgcd(b,a);
    if(b == 0) return a;
    pgcd(b, a % b);
}

long find(max, min){
    long p = min;
    while(++p < max){
        if(pgcd(p, max) == 1 && pgcd(p, min) == 1) return p;
    }
}

