typedef struct _cell {
	int val;
	int pos;
}CELL;

int cmp(const void* a, const void* b)
{
	if (((CELL*)a)->val == ((CELL*)b)->val) {
		return ((CELL*)a)->pos - ((CELL*)b)->pos;
	}
	return ((CELL*)b)->val - ((CELL*)a)->val;
}

int cmp2(const void* a, const void* b)
{
	return ((CELL*)a)->pos - ((CELL*)b)->pos;
}

