		for (i = 0; i < n; i++) {
			scanf("%d", &a[i].val);
			a[i].pos = i + 1;
		}
		qsort(a, n, sizeof(a[0]), cmp);
		printf("%d\n", a[k-1].val);
		qsort(a, k, sizeof(a[0]), cmp2);
		for (i = 1; i <= k; i++) {
			printf("%d%c", a[i-1].pos, i < k ? ' ' : '\n');
		}
	}
	return 0;
}

