long long judge(int k)
{
    long long sum, t, x;

    sum = (a-k)*(a-k);
    t = b%(k+2);
    x = b/(k+2);
    sum -= (k+2-t)*x*x;
    sum -= t*(x+1)*(x+1);
    sum += k;

    return sum;
}


void output(int k)
{
    int t, x, i;

    t = b%(k+2);
    x = b/(k+2);
    for (i=0; i<x; i++)
        putchar('x');
    if (t) {
        putchar('x');
        t--;
    }   
    for (i=0; i<a-k; i++)
        putchar('o');
    while (k--) {
        for (i=0; i<x; i++)
            putchar('x');
        if (t) {
            putchar('x');
            t--;
        }   
        putchar('o');
    }
    for (i=0; i<x; i++)
        putchar('x');
    if (t) {
        putchar('x');
        t--;
    }   
    putchar('\n');

    return;
}

