		scanf("%d",&(ar[i].l));
	for(i=0;i<n;i++)
		scanf("%d",&(ar[i].d));
	qsort(ar,n,sizeof(LEG),cmp);
	for(i=0;i<100005;i++)
		count[i]=0;
	now=-1;
	ncost=0;
	for(i=n-1;i>=0;i--){
		count[ar[i].l]++;
		if(ar[i].l!=now){
			cost[ar[i].l]=ncost;
			now=ar[i].l;
		}
		ncost+=ar[i].d;
	}
	i=0;
	now=-1;
	ncount=0;
	ans=1000000007;
	while(i<n){
		if(ar[i].l==now){
			dc[ar[i].d]++;
			i++;
			ncount++;
		}
		else{
			now=ar[i].l;
			left=ncount;
			if(left<count[ar[i].l]){
				if(ans>cost[ar[i].l]){
					ans=cost[ar[i].l];
					db1=ar[i].l;
					db2=cost[ar[i].l];
					db3=0;
