				ncost=cost[ar[i].l];
				j=left+1-count[ar[i].l];
				k=1;
				while(j>0&&k<=200){
					if(dc[k]>j){
						ncost+=k*j;
						j=0;
					}
					else{
						ncost+=dc[k]*k;
						j-=dc[k];
					}
					k++;
				}
				if(j==0&&ncost<ans){
					ans=ncost;
					db1=ar[i].l;
					db2=cost[ar[i].l];
					db3=ncost;
				}
			}
			dc[ar[i].d]++;
			i++;
