void mergeSort(int low,int mid,int high){
    int i,m,k,l;
    l=low;
    i=low;
    m=mid+1;
    while((l<=mid)&&(m<=high)){
         if(a[l][0]<=a[m][0]){
             temp[i][0]=a[l][0];
             temp2[i][0]=b[l][0];
             temp[i][1]=a[l][1];
             temp2[i][1]=b[l][1];
             l++;
         }
         else{
             temp[i][0]=a[m][0];
             temp2[i][0]=b[m][0];
             temp[i][1]=a[m][1];
             temp2[i][1]=b[m][1];
             m++;
         }
         i++;
    }
    if(l>mid){
         for(k=m;k<=high;k++){
             temp[i][0]=a[k][0];
             temp2[i][0]=b[k][0];
             temp[i][1]=a[k][1];
             temp2[i][1]=b[k][1];
             i++;
         }
    }
    else{
         for(k=l;k<=mid;k++){
             temp[i][0]=a[k][0];
             temp2[i][0]=b[k][0];
             temp[i][1]=a[k][1];
             temp2[i][1]=b[k][1];
             i++;
         }
    }
    for(k=low;k<=high;k++){
         a[k][0]=temp[k][0];
         b[k][0]=temp2[k][0];
         a[k][1]=temp[k][1];
         b[k][1]=temp2[k][1];
    }
}
void partition(int low,int high){
    int mid;
    if(low<high){
         mid=(low+high)/2;
         partition(low,mid);
         partition(mid+1,high);
         mergeSort(low,mid,high);
    }
}

