void q_sort(int *a, int left, int right)
{
    int i, j, k, t;
    if (left < right) {
        i = k = left;
        j = right + 1;
        while (1) {
            while (a[++i] < a[k]);
            while (a[--j] > a[k]);
            if (i >= j) break;
            t = a[i];
            a[i] = a[j];
            a[j] = t;
        }
        t = a[k];
        a[k] = a[j];
        a[j] = t;
        q_sort(a, left, j-1);
        q_sort(a, j+1, right);
    }
}

int visit(int *a, int i, int j)
{
    if (j>1 && (a[i] + 1) == a[i+1]) {
        //printf("%d -> %d\n", a[i], a[i+1]);
        return visit(a, i+1, j-1);
    } else if (j>1 && (a[i]) == a[i+1]) {
        return visit(a, i+1, j);
    }
    if (j == 1) return 1;
    return 0;
}
