int mod=1000000007;

long long po(long long x, long long y)
{
	long long pro=1;
	while(y>0)
	{
		if(y&1 != 0)
			pro=((pro%mod)*(x%mod))%mod;
		x=(x*x)%mod;
		y=y>>1;
	}
	return pro%mod;
}

