		{
			if (y1>y2&&y1>y3){a=k;scanf("%lf%lf",&x1,&y1);k++;continue;}
			if (y2>y1&&y2>y3){b=k;scanf("%lf%lf",&x2,&y2);k++;continue;}
			if (y3>y1&&y3>y2){c=k;scanf("%lf%lf",&x3,&y3);k++;continue;}
		}
		else
