		if (judge(x1,y1,x2,y2,x3,y3,x,y)>0&&judge(x3,y3,x1,y1,x2,y2,x,y)>0)
		{
			x2=x;
			y2=y;
			b=i;
			continue;
		}
		if (judge(x1,y1,x2,y2,x3,y3,x,y)>0&&judge(x3,y3,x2,y2,x1,y1,x,y)>0)
		{
			x1=x;
			y1=y;
			a=i;
			continue;
		}
		if (judge(x3,y3,x2,y2,x1,y1,x,y)>0&&judge(x3,y3,x1,y1,x2,y2,x,y)>0)
		{
			x1=x;
			y1=y;
			a=i;
			continue;
