void solve(int sum,int limit,int grade,int code)
{
	if(sum == 0||grade==0)
		return ;
	int t = code*grade ;
	if(sum>=grade&&t<=limit)
	{
		result[num] = t ;
		num++ ;
		code += 2 ;
		sum = sum-grade ;
	}
	else
	{
		grade = grade/2 ;
		code = 1 ;	
	}
	solve(sum,limit,grade,code) ;	
	return ;
}

