double median(int *T)
{
    return ((double)T[1]+(double)T[2])/2;
}

double arithmetic(int *T)
{
    return ((double)T[0]+(double)T[1]+(double)T[2]+(double)T[3])/4;
}

double range(int *T)
{
    return ((double)T[3]-(double)T[0]);
}

int cmp(const void *a, const void *b)
{
    if (*(int*)a > *(int*)b)
        return 1;
    else if (*(int*)a == *(int*)b)
        return 0;
    else
        return -1;
}

int sort(int *T, int k)
{
    int echanger = 1,i;
    while (echanger == 1)
    {
        echanger = 0;
        for (i=0;i<3;++i)
        {
            if (T[i] > T[i+1])
            {
                if (k == i)
                    k = i+1;
                else if (k==(i+1))
                    k = i;
                int aux = T[i];
                T[i] = T[i+1];
                T[i+1] = aux;
                echanger = 1;
            }
        }
    }

    return k;
}

