		}
		else
		{
			if((int)('z'-str[i])<=k)
			{
				k-=(int)('z'-str[i]);
				str[i]='z';
			}
			else
			{
				str[i]=(char)((int)str[i]+k);
				k=0;
			}
		}
		i++;
	}
	if(k>0)
		printf("-1\n");
	else
		printf("%s\n",str);
	return 0;
}

