double power(double base, double exp){
  double result = 1.0f;
  int i;
  for (i = 0; i < exp; i++) {
    result *= base;
  }
  return result;
}

double maxExpected(double numFace, double numTrail){
  double e = 0.0f;
  double i;
  for (i = 1.0f; i <= numFace; i+=1.0f) {

    e += i * (pow(i/numFace, numTrail) - pow((i-1.0f)/numFace, numTrail));
  }
  return e;
}

