long long removeZero(long long a)
{
    long long i,num=0;


    for(i=0; a != 0; i++)
    {
        if(a%10 != 0)
        {
            num = num * 10 + a % 10;
        }
        a = a/10;
    }

    for(i=0; num != 0; i++)
    {
        a = a * 10 + num % 10;
        num = num / 10;
    }



    return a;
}

