        for(i=0; i<N; i++){
            int v1, v2, w;
            scanf("%d%d%d", &v1, &v2, &w);

            graph[v1][v2] = w;
            sum+=w;
        }


        int res = DFS(1);

        int ans = res<(sum-res)?res:(sum-res);
        printf("%d", ans);
    }

    return 0;
}

