#include<stdio.h>
#define N 1000
#include<stdlib.h>
#include<math.h>
#define MAX_N 10000
int heap[MAX_N],size=0;
void print(){
	int i;
	for(i=0;i<size;i++){
		printf(" %d",heap[i]);
	}
	printf("\n");
}

void push(int x) {
	int i=size;
	size++;
	while(i>0) {
		int p=(i-1)/2;
		if(heap[p]>=x) break;//父亲节点小于等于儿子节点就停止！
		//儿子节点就放这个新值
		heap[i]=heap[p];//新儿子节点上放上了父亲节点的值！
		//相当于把父节点下移一层
		i=p;//这时儿子可能要放在父节点上
	}
	heap[i]=x;
}
int pop() {
	int ret=heap[0];
	size--;
	int x=heap[size];
	//这里也只是提取了最后一个元素，但是这种提取也是没有必要的！

	int i=0;
	while(i*2+1<size) {
		int a=i*2+1,b=i*2+2;
		int max=a;
		if(b<size && heap[b]>heap[a]) max=b;//保证左边儿子的值
		//这里不是保证左边儿子比右边儿子小，
		//只是取两个儿子中的最小值，来进行比较。
		//即使左边儿子比右边的大，这里也没有做出一种更换！
		if(heap[max]<=x) break;//认为heap[0]=x;=最后一个数
		heap[i]=heap[max];
		i=max;
	}
	heap[i]=x;
	return ret;
}
void sort(int a[],int n){
	int i,j;
	for(i=0;i<n-1;i++){
		int min=i;
		for(j=i+1;j<n;j++){
			if(a[j]<a[min]){
				min=j;
			}
		}
		if(min!=i){
			int tmp=a[min];
			a[min]=a[i];
			a[i]=tmp;
		}
	}
}
