		*owner = 2;
}

short getWinner(short a, short b) {
	if(a == b)
		return -1;
	if(a == 0) {
		if(b == 1) return 1;
		return 0;
	}
	if(a == 1) {
		if(b == 0) return 0;
		return 1;
	}
	if(a == 2) {
		if(b == 0) return 1;
		return 0;
	}
}

