typedef struct seq_ seq;

struct seq_
{
    int *arr;
    int n;
};

seq *MakeSeq(int n)
{
    seq *s;
    s = (seq *) malloc(sizeof(seq));
    s->arr = (int *) malloc(sizeof(int)*n);
    s->n=n;
    return s;
}

seq *Refuel(double alpha, int n)
{
    seq *s;
    int c;

    s = MakeSeq(n);

    for( c = 1; c <= s->n; c++ )
    {
        s->arr[c-1] = ((alpha*c)/10);
    }
    return s;

}

