void PrintSeq(seq *s)
{
    int c;
    for( c=0; c < s->n; c++)
    {
        printf("%i ",s->arr[c]);
    }
    printf("\n");
}


int CmpSeq(seq *s1, seq *s2,int eqc)
{
    int c;
    int n;

    if( s1->n < s2->n) n = s1->n;
    else n = s2->n;

    for( c = 0; c < n; c++ )
    {

     if( s1->arr[c] > s2->arr[c]) return 1;
     if( s1->arr[c] < s2->arr[c]) return -1;

    }
    return eqc;
}



seq *ReadSeq(FILE *f)
{
    int na,c;
    seq *s;
    fscanf(f,"%i",&na);
    s = MakeSeq(na);

    for( c = 0; c < na; c++ )
    {

        fscanf(f,"%i ", s->arr +c);

    }
    return s;

}


double FindMaxAlpha(seq *s)
{
  return  (s->arr[2] - s->arr[1] + 1)*10;
}


double mpd(double a, double b, seq *s,int eqc)
{
    int fa,fb,fc;
    double c,cold;

    c=0;
    cold = 1;

    do
    {
        cold=c;
        c = fabs(a + b) / 2;
       // printf("a = %f, b = %f, c = %f\n",a,b,c);
        fa=CmpSeq(Refuel(a,s->n), s,eqc);
        fb=CmpSeq(Refuel(b,s->n), s,eqc);
        fc=CmpSeq(Refuel(c,s->n), s,eqc);

        if(fa*fc < 0) b = c;
        else
        if(fc*fb < 0) a = c;
       // if( fa == 0) b=c;
       // if( fb == 0) a=c;

    }while( /*fc != 0*/ fabs(cold - c)> eps);
    return fabs(a+b)/2;
}


