#include<stdio.h>

void sortelements(int n,int a[])
{
    int min,idx,i,j,t;
    for(i=0; i<n-1; i++)
    {
        min=a[i];
        idx=i;
        for(j=i+1; j<n; j++)
        {
            if(a[j]<min)
            {
                min=a[j];
                idx=j;
            }
        }
        t=a[i];
        a[i]=a[idx];
        a[idx]=t;

    }
}


