	int	au;
	int	sub;
} snd_t;

snd_t	mov[200006];
lg_t	lcnt[200006];
lg_t	lli[200006];
int	inl[200006];

int cntcom (const void *a, const void *b)
{
        lg_t     *x = (lg_t  *)a;
        lg_t	 *y = (lg_t *)b;

        return (y->cnt - x->cnt);
}
int lcomp (const void *a, const void *b)
{
        lg_t     *x = (lg_t  *)a;
        lg_t	 *y = (lg_t *)b;

        return (x->li - y->li);
}

int descomp (const void *a, const void *b)
{
        int     x = *(int  *)a;
        int	y = *(int *)b;

        return (y - x);
}


int main(int argc, char *argv[])
{
