	int	cnt = 0;
	int	lc = 0;
	int	ans = 1;
	int	amx = 0;
	int	smx = 0;

	scanf ("%d", &n);

	for (i = 0; i < n; ++i) {
		scanf ("%d", &inl[i]);
	}

	qsort (inl, n, sizeof (*inl), descomp);

	for (i = 0; i <= n; ++i) {
		if (cl != inl[i]) {
			if (cnt) {
				lcnt[lc].li = cl;
				lcnt[lc++].cnt = cnt;
			}		
			cl = inl[i];
			cnt = 0;
		}
		++cnt;
	}
	memcpy (lli, lcnt, lc * sizeof (*lcnt));
	qsort (lcnt, lc, sizeof (*lcnt), cntcom);
	qsort (lli, lc, sizeof (*lli), lcomp);

