		int	ac = 0, sc = 0;
		tmp.li = mov[i].au;

		res = bsearch (&tmp, lli, lc,
				sizeof (*lli), lcomp);

		if (res) {
			ac = res->cnt;
		}

		tmp.li = mov[i].sub;

		res = bsearch (&tmp, lli, lc,
				sizeof (*lli), lcomp);

		if (res) {
			sc = res->cnt;
		}

		if (ac > amx) {
			ans = i+1;
			amx = ac;
			smx = sc;
