	for (i = 0; i < n; i++)
	{
		scanf("%d %d", &x, &y);
		r1[i] = p2(x1 - x) + p2(y1 - y);
		r2[i] = p2(x2 - x) + p2(y2 - y);
	}

	minval = d18;
	for (i = 0; i < n; i++)
	{
		bet = r1[i];
		maxr2 = 0;
		for (j = 0; j < n; j++)
			if (r1[j] > bet)
				if (r2[j] > maxr2)
					maxr2 = r2[j];
		minval = min(minval, bet + maxr2);
	}

	for (i = 0; i < n; i++)
	{
		bet = r2[i];
		maxr1 = 0;
		for (j = 0; j < n; j++)
			if (r2[j] > bet)
				if (r1[j] > maxr1)
					maxr1 = r1[j];
		minval = min(minval, bet + maxr1);
	}

	while (minval/d18 == 0)
		d18 /= 10;
	while (d18)
	{
		printf("%d", minval/d18);
		minval %= d18;
