	for (u = 0; u < n; u++)
		for (v = 0; v < n; v++) {
			t[u][v] = -1000000000;
			for (w = 0; w < n; w++)
				t[u][v] = max(t[u][v], a[u][w] + b[w][v]);
		}

	memcpy(a, t, sizeof(t));
}

