            lever[i]=0;
        else
            lever[i]-='0';
    }
    for (i=0; i<pivot; i++)
    {
        moment_l+=lever[i]*(pivot-i);
    }
    for (i=pivot+1; i<strlen(lever); i++)
    {
        moment_r+=lever[i]*(i-pivot);
    }
