int max(int a , int b){
	if(a>=b) return a;
	return b;
}
int min(int a , int b){
	if(a>b) return b;
	return a;
}
typedef struct node{
	int val;
	struct node* next;
}node;

typedef struct stack{
	node* startnode;
	int size;
}stack;

void push(stack* given , int value){
	if(given->startnode == NULL){
		given->startnode = (node*)malloc(sizeof(node));
		given->startnode->val = value;
		given->startnode->next = NULL;
		(given->size)++;
		return;
	}
	node* temp;
	temp = (node*)malloc(sizeof(node));
	temp->val = value;
	temp->next = given->startnode;
	given->startnode = temp;
	(given->size)++;
	return;

}

int top(stack* given){
	if(given->startnode)
		return given->startnode->val;
	return INF;
}

int size(stack* given){
	return given->size;
}

bool isempty(stack* given){
	if(given->size==0)
		return true;
	return false;
}

void pop(stack* given){
	if(isempty(given)){
		//printf("Stack is empty!\n");
		return;
	}
	node* temp = given->startnode;
	given->startnode = given->startnode->next;
	(given->size)--;
	free(temp);
	return;
}


