void shot(int a[],int m,int n,int N){
	if(m==0){
		a[1]+=a[0]-n;
		a[m]=0;
	}
	else if(m==N){
		a[m-1]+=n-1;
		a[m]=0;
	}
	else{
		a[m+1]+=a[m]-n;
		a[m-1]+=n-1;
		a[m]=0;
	}
}
