int partition(int number[],int i,int j)
{
    int key;
    key=number[i];
    while(i<j)
    {
        while(i<j&&number[j]>key) j--;
        if(i<j) {
            number[i]=number[j]; i++;
        }
        while(i<j&&number[i]<key) i++;
        if(i<j){
            number[j]=number[i]; j--;
        }
    }
    number[i]=key;
    return i;
}
void q_sort(int number[],int i,int j)
{
    int temp;
    if(i<j)
    {
        temp=partition(number,i,j);
        q_sort(number,i,temp-1);
        q_sort(number,temp+1,j);
    }
}
