void go(int down,int up,int len) {
	int i;
	if (len>distance) {
		distance=len;
		end=down;
	}
	for (i=1;i<=n;i++)
		if (x[down][i]&&i!=up&&i!=blown)
			go(i,down,len+1);
}

int travel(int start,int fuse) {
	blown=fuse;
	end=start;
	distance=0;
	go(start,fuse,0);
	distance=0;
	go(end,fuse,0);
	return distance;
}

