int palindrome(char checkstring[12], int length){
	int count = 0, i;
	for (i = 0; i < (length+1) / 2; i++){
		if (checkstring[i] == checkstring[length - i])
			count++;
	}
	if (count == (length + 1) / 2)
		return 1;
	else
		return 0;
}

