  ll ans = 0, i, j, k, t;
  for (i = 1; i < w; i ++) {
    for (j = 1; j < h; j ++) {
      k = i;
      k = MIN(k, w - i);
      t = j;
      t = MIN(t, h - j);
      ans += k * t;
    }
  }
  printf("%lld\n", ans);
}

