int x[100000], y[100000], a[100000], di;

int less(int i, int j) {
	if (di == 0)
		return y[i] < y[j];
	else if (di == 1)
		return x[i] < x[j];
	else
		return x[i] < x[j];
}

void sort(int l, int r) {
	if (l >= r)
		return;

	int i = l, j = r, p = a[(l + r) / 2];
	while (i <= j)
		if (less(a[i], p))
			i++;
		else if (less(p, a[j]))
			j--;
		else {
			int t = a[i]; a[i] = a[j]; a[j] = t;
			i++; j--;
		}

	sort(i, r); sort(l, j);
}

