#define REP(i,a,b) for(i=a;i<b;i++)
#define rep(i,n) REP(i,0,n)

#define ll long long

int solve(int st, int x[], int n, ll step){
  int i;
  int now = st;

  now = st;
  rep(i,step){
    if(i && i%n==0 && now==st){
      step %= i; i=0;
      if(step==0) break;
    }
    now += 2*(x[i%n]-now);
  }
  return now;
}

