int reverse(char k)
{
    char num[9];
    memset(num,0,9);
    int i;
    for(i=0; i<8; i++)
    {
             if(k%2)
                    num[i] = '1';
             else
                    num[i] = '0';
             k /= 2;
    }
    num[8]=0;
    int re = bit_dec(num);
    return re;
}
