void ordenar(int v[], int n)
{
    int i, j;

    for(i=0; i<n-2; i++)
    {
        for(j=0; j<n-i-1; j++)
        {
            if(v[j]>v[j+1])
            {
                swap(&v[j], &v[j+1]);
            }

        }
    }
}

void swap(int *a, int *b)
{
    int aux;
    aux = *a;
    *a=*b;
    *b=aux;

}

