long long findMinOnes(long long n,int i)
{
	int count = 0;
	long long value1,value2;
	if(n<0)
		n *=-1;
	if(i==1)
		return n;
	if(n==1)
		return 1;
		while(n>a[i])
		{
			n-= a[i];
			count+=i;
		}
		value1 = count + findMinOnes(n,i-1);
		n-= a[i];
		count+=i;
		value2 = count + findMinOnes(n,i-1);
		if(value1 < value2)
			return value1;
		else
			return value2;
}
