int iguales(int i){
    return m[i][0]==m[i][1] && m[i][1]==m[i][2];
}
int cap(int n){
    return ret(n,0,1,2) || ret (n,1,2,0) || ret (n,2,0,1);
}
int ret(int n,int x,int y, int z){
    return m[n][x]==m[n][y] && !into(m[!n][z],m[!n][x],m[!n][y]);
}
int into(int v, int x, int y){
    return v>min(x,y) && v<max(x,y);
}
int min(int x,int y){
    if(x<y){
        return x;
    }else{
        return y;
    }
}
int max(int x,int y){
    if(x>y){
        return x;
    }else{
        return y;
    }
}

