	while(add)
	{
		if(add&1)
		{
			if(y==Now.y&&x>=Now.x&&x<=Now.x+add)
			{
				Res=((add-1)<<1)+1;
				break;
			}
			Now.x+=add;
			if(x==Now.x&&y>=Now.y&&y<=Now.y+add)
			{
				Res=add<<1;
