  unionInit(ind,n);
  while(m--){
    scanf("%d%d",&i,&j);
    unionConnect(ind,i-1,j-1);
  }

  rep(i,n) num[i] = 0;
  rep(i,n) num[unionGet(ind,i)]++;
  g = 0;
  res = 1;

  rep(i,n) if(num[i]){
    res *= num[i];
    res %= MOD;
    g++;
  }
  if(g==1){
    res = 1 % MOD;
  } else {
    res *= pw(n, g-2, MOD);
    res %= MOD;
  }
  printf("%d\n",(int)res);

