void merge(int bas,int orta,int son){
	int i=bas,j=orta,s=bas;

	while(i < orta && j < son)
		yeni[s++] = (arr[i] < arr[j]) ? arr[i++] : arr[j++];

	while(i < orta) yeni[s++] = arr[i++];
	while(j < son)  yeni[s++] = arr[j++];

	for(i=bas;i<son;i++) arr[i]=yeni[i];
}

void sort(int bas,int son){
	if(bas+1 >= son) return;
	int orta = (bas+son)/2;
	sort(bas,orta);
	sort(orta,son);
	merge(bas,orta,son);
}

