                    new_l = false;
                    n_first = true;
                }
            }
            else if(ch == ' ')
            {
                if(new_l)
                {
                    continue;
                }
                else
                {
                    putchar('>');
                    new_l = true;
                }
            }
            else
            {
                if(new_l)
                {
                    if(n_first)
                        putchar('\n');
                    putchar('<');
                    putchar(ch);
                    new_l = false;
                    n_first = true;
                }
                else
                {
                    putchar(ch);
                }
            }
        }
    }
    if(!new_l)
    {
        putchar('>');
    }
    return 0;
}

