typedef struct Queue{
    int arr[2000];
    int head;
    int tail;
}Queue;
int IsEmpty(Queue *q)
{
    if(q->head==q->tail) return 1;
    else return 0;
}
void Enqueue(Queue *q,int a)
{
    q->arr[q->tail]=a;
    q->tail++;
}
int Dequeue(Queue *q)
{
    q->head++;
    return q->arr[q->head-1];
}
