    y=min(a,b);
    if(t==1 && y==1 && x!=y)
    {
        printf("0/1");
        return 0;
    }
    m=gcd(x,y);
    if((((x/m)*(y/m))*m)/(x/m)==y)
    {
        k=((x/m)*(y/m))*m;
        l=t/k;
        a=y*l;
        //printf("%lld %lld %lld\n",l,t,k);
        b=t%k;
        if(b<y)
            a+=b;
