#include <stdio.h>
#include <stdlib.h>

void quick_sort(long long *a, long long *b, long long n) {

	int i, j, p, t;
	if (n < 2)
		return;
	p = a[n / 2];
	for (i = 0, j = n - 1;; i++, j--)
	{
		while (a[i] < p)
			i++;
		while (p < a[j])
			j--;
		if (i >= j)
			break;
		t = a[i];
		a[i] = a[j];
		a[j] = t;
		t = b[i];
		b[i] = b[j];
		b[j] = t;
	}
	quick_sort(a, b, i);
	quick_sort(a + i, b + i, n - i);
}


