int a[100001],temp[100001];
void mergeSort(int low,int mid,int high){
    int i,m,k,l;
    l=low;
    i=low;
    m=mid+1;
    while((l<=mid)&&(m<=high)){
         if(a[l]<=a[m]){
             temp[i]=a[l];
             l++;
         }
         else{
             temp[i]=a[m];
             m++;
         }
         i++;
    }
    if(l>mid){
         for(k=m;k<=high;k++){
             temp[i]=a[k];
             i++;
         }
    }
    else{
         for(k=l;k<=mid;k++){
             temp[i]=a[k];
             i++;
         }
    }
    for(k=low;k<=high;k++){
         a[k]=temp[k];
    }
}
void partition(int low,int high){
    int mid;
    if(low<high){
         mid=(low+high)/2;
         partition(low,mid);
         partition(mid+1,high);
         mergeSort(low,mid,high);
    }
}
