void mergesort(int ii, int p, int q, int r)
{
	int i, j, k, n1, n2;

	n1 = q-p+1;
	for (i=0; i<n1; i++)	aa[i] = a[ii][p+i];  aa[n1].v = 999999999;

	n2 = r-q;
	for (i=0; i<n2; i++)	bb[i] = a[ii][q+i+1];  bb[n2].v = 999999999;

	i=0; j=0;
	for (k=p; k<=r; k++)
	if  (aa[i].v < bb[j].v)
		a[ii][k] = aa[i++];
	else
		a[ii][k] = bb[j++];
}

void merge(int ii, int p, int r)
{
	if (p<r)
	{
		int q = (p+r)/2;
		merge(ii, p, q);
		merge(ii, q+1, r);
		mergesort(ii, p, q, r);
	}
}

