};

int cmp1 (const void *a, const void *b)
{
    struct point *m = (struct point *)a, *n = (struct point *)b;
    return m->x - n->x;
}

int cmp2 (const void *a, const void *b)
{
    struct point *m = (struct point *)a, *n = (struct point *)b;
    return m->idx - n->idx;
}

