        while(p)
        {
            now=p->which;
            if(!used[now])
            {
             que[e]=now,nd[que[e]]->num=ini[now],nd[que[e]]->signj=nd[que[s]]->signj,nd[que[e]]->signj=nd[que[s]]->signj,nd[que[e]]->deep=nd[que[s]]->deep+1;
             used[now]=1;
             e++;
            }
            p=p->next;
        }
        s++;
    }
    return t;
}
