void sort(Segment *Vec,int g)
{
    int j=0;
    do
    {
    j++;
        int k=j;
        while(k<=g)
        {
            k++;
            if(Vec[j].s1!=Vec[k].s1)
            {
                if(Vec[j].s1>Vec[k].s1)
                {
                   Segment tmp=Vec[j];
                    Vec[j]=Vec[k];
                    Vec[k]=tmp;
                }
