double Exp(double n, int m)
{
    if(m == 0) {
        return 1;
    }
    double k = 1;
    while(m != 1) {
        if(m & 1) {
            k = k * n;
        }
        n = n * n;
        m >>= 1;
    }
    return n * k;
}

