int compute(int *a, int *b, const int l, const int r) {
    int i, a_or, b_or;
    a_or = a[l];
    b_or = b[l];

    for(i = l + 1; i <= r; i++) {
        a_or |= a[i];
        b_or |= b[i];
    }

    return (a_or + b_or);
}

