void selectionSort(int a[], int n){
    int min, idx, i, t, j;
    for(j=0; j<n-1; j++){
        idx = j;
        min = a[j];
        for(i=j+1; i<n; i++){
            if(min>a[i]){
                min = a[i];
                idx= i;
            }
        }
        t = a[j];
        a[j] = a[idx];
        a[idx] = t;

    }
}

