    scanf("%lld",&a);
    scanf("%lld",&b);
    scanf("%lld",&c);
    for(i=1;i<=a;i++)
    {
        dp[i][0]=0;
        for(j=1;j<c;j++)
        {
            if(i-j<0)
                break;
            dp[i][0]+=dp[i-j][0];
            if(dp[i][0]>1000000007)
                dp[i][0]-=1000000007;
        }
    }
    for(i=1;i<=a;i++)
    {
        dp[i][1]=0;
        for(j=1;j<=b;j++)
        {
            if(i-j<0)
                break;
            dp[i][1]+=dp[i-j][1];
              if(dp[i][1]>1000000007)
                dp[i][1]-=1000000007;
        }
    }
    e=dp[a][1]-dp[a][0];
    if(e<0)
        e=e+1000000007;
    f=e%1000000007;
    printf("%lld",f);
    return 0;
}

#include<stdio.h>
#include<stdlib.h>
int cmp(const void *a,const void *b) 
{ 
return *(int *)a-*(int *)b; 
} 
int main(int argc, char *argv[])
{
	int n,time,t[100],d[5000];
	int i,j,k=0;
	while(scanf("%d",&n)!=EOF)
	{
		for(i=0;i<n;i++)
		scanf("%d",&t[i]);
		scanf("%d",&time);
		qsort(t,i,sizeof(t[0]),cmp);
		for(j=i-1;j>=0;j--)
		{
			for(i=0;i<=j;i++)
			{
				if((t[j]-t[i])<=time)
				d[k++]=j-i+1;
			}
		}
		qsort(d,k,sizeof(d[0]),cmp);
		printf("%d\n",d[k-1]);
	}
	return 0;
}

