#define N 500

void sort (int *l, int *r) {
  int *i = l, *j = r, p = l[(r - l + 1)/2], tmp;
  while (i <= j) {
    while (*i < p) ++i;
    while (p < *j) --j;
    if (i <= j) {
      tmp = *i; *i = *j; *j = tmp;
      ++i; --j;
    }
  }
  if (i < r) sort (i, r);
  if (l < j) sort (l, j);
}


int main(int argc, char *argv[]) {
