  for (i = 0; i < n; ++i) scanf ("%d", &a[i]);
  while (sort (a, a+n-1), a[(n-1)/2] != x) { ++res; a[n++] = x; }
  printf ("%d\n", res);
  exit (EXIT_SUCCESS);
return 0;
}

