int At_Univer(int *table, int len)
{
    int i,k=0;
    if (*table==1)
        k=1;
    for(i=1;i<len-1;i++)
        if (table[i]==1)
	    k++;
	else
	    if ((table[i-1]==1)&&(table[i+1]==1))
	        k++;
    if ((len!=1)&&(table[len-1]==1))
        k++;
    return k;
}


