void A(int ZA[], int ZB[], int a, int b)
{
	int c, d, e, f;

	if (a < b) {
		c = (b - a + 1) / 2 + a;
		A(ZA, ZB, a, c - 1);
		A(ZA, ZB, c, b);
		d = c - 1;
		e = a;
		f = 0;
		while (e <= d && c <= b) {
			if (ZA[e] < ZA[c]) {
				ZB[f] = ZA[e];
				e += 1;
			} else {
				ZB[f] = ZA[c];
				c += 1;
			}
			f += 1;
		}
		while (e <= d) {
			ZB[f] = ZA[e];
			e += 1;
			f += 1;
		}
		while (c <= b) {
			ZB[f] = ZA[c];
			c += 1;
			f += 1;
		}
		while (f > 0) {
			ZA[a + f - 1] = ZB[f - 1];
			f -= 1;
		}
	}
}

