    }
    if(b>a)
    {
        temp=a;
        a=b;
        b=temp;
    }
    g = gcd(a,b);
    if(b/g>t/a)
    {
        if(b-1>t)
        ans=t;
        else
        ans=b-1;
        g=gcd(ans,t);
        ans=ans/g;
        t=t/g;
        printf("%lld/%lld",ans,t);
        return 0;
    }
    l = (a/g)*b;

    ans += t/l;

    ans += (t/l)*(b-1);
