int merge(long long int* a,long long int* b,long long int* c,long long int* d,long long int s,long long int e){
	if(s>=e)
		return 0;
	merge(a,b,c,d,s,(s+e)/2);
	merge(a,b,c,d,((s+e)/2)+1,e);
	int i = s,j=((s+e)/2)+1,n = s;
	while(i <= (s+e)/2 || j <= e)
		if(a[i] <= a[j] && i <= (s+e)/2){
			b[n] = a[i];
			d[n] = c[i];
			i++;
			n++;
		}
		else
			if(a[i] >= a[j] && j <= e){
				b[n] = a[j];
				d[n] = c[j];
				j++;
				n++;
			}
			else
				if(i > (s+e)/2)
					while(j <= e){
						b[n] = a[j];
						d[n] = c[j];
						j++;
						n++;
					}
				else
					while(i <= (s+e)/2){
						b[n] = a[i];
						d[n] = c[i];
						i++;
						n++;
					}
	for(i=s;i<=e;i++) {
		a[i] = b[i];
		c[i] = d[i];
	}
	return 0;
}
