int overlapfactor(int x, int y) {
	int i, ret=0;
	for (i=0; i<na&&i+x<nb; ++i) {
		int j;
		for (j=0; j<ma&&j+y<mb; ++j) if (i+x>=0&&j+y>=0) {
			ret+=a[i][j]*b[i+x][j+y];
		}
	}
	return ret;
}

