void recur(int cur, int idx, int *cnt)
{
    int i;
    v[cur] = 1;
    ans[idx][(*cnt) ++] = cur + 1;
    if ((*cnt) > 3)
    {
    return;
    }
    for (i = 0; i < c[cur]; i ++)
    {
    if (v[g[cur][i]] == 0)
    {
        recur(g[cur][i], idx, cnt);
        if ((*cnt) > 3)
        {
        return;
        }
    }
    }
}

void solve(int n)
{
    int i, j, size, cnt, cntone, cnttwo;
    memset(v, 0, n * sizeof(int));
    for (i = j = 0; i < n; i ++)
    {
    if (v[i] == 0)
    {
        cnt = 0;
        recur(i, j, &cnt);
        if (cnt > 3)
        {
        printf("-1\n");
        return;
        }
        len[j ++] = cnt;
    }
    }
    size = j;
    cntone = cnttwo = 0;
    for (i = 0; i < size; i ++)
    {
    if (len[i] == 1)
    {
        cntone ++;
    }
    else if (len[i] == 2)
    {
        cnttwo ++;
    }
    }
    if (cntone < cnttwo)
    {
    printf("-1\n");
    return;
    }
    memset(v, 0, size * sizeof(int));
    for (i = 0; i < size; i ++)
