        current = 0;
        for (j = 0; j  < 3; ++j) {
            current += pow(w[0][j] - p[i][j], 2.0);
        }
        result = max(result, current);
    }
    return result;
}   

double g() {
    double result = .0, current = .0;
    int i, j;
    for (i = 0; i < n; ++i) {
        current = 0;
        for (j = 0; j  < 3; ++j) {
            current += pow(w[1][j] - p[i][j], 2.0);
        }
        result = max(result, current);
    }
    return result;
}   

double go(int coordinate) {
    if (coordinate == 3) {
        double fR = f(), gR = g();
        if (gR < fR) {
            memcpy(w[0], w[1], 24);
        }
        return gR;
    } else {
        double l = -1e4, r = 1e4, a, b, fA, fB, step;
        while (l + EPS < r) {
            step = (r - l) / 3;
            a = l + step;
            b = r - step;
            w[1][coordinate] = a;
            fA = go(1 + coordinate);
            w[1][coordinate] = b;
            fB = go(1 + coordinate);
            if (fA < fB) {
                r = b;
            } else {
                l = a;
            }
        }
        w[1][coordinate] = (l + r) / 2;
        return go(1 + coordinate);          
    }
