struct line {
  int64_t k;
  int64_t b;
  int64_t y1;
  int64_t y2;
};
int linecmp(const void* a, const void* b)
{
  struct line* c = (struct line*) a;
  struct line* d = (struct line*) b;
  if (c->y1 == d->y1) {
    return (c->y2 > d->y2) - (c->y2 < d->y2);
  } else {
    return (c->y1 > d->y1) - (c->y1 < d->y1);
  }
}

