     else n1=n;
     if(d<0) d1=(-1)*d;
     else d1=d;
     if(n1>d1) max = n1;
     else max=d1;
     p=n1;
     q=d1;

     for(i=2;i<=max;i++)
     {
      if(n1%i ==0 && d1%i ==0)
      {
          while (n1%i ==0 && d1%i ==0)
        {n1/=i;
        d1/=i;}
        }
      }
      if(d<0 && n>0)
     printf("-%d/%d",n1,d1);
     if(d<0 && n<0)
     printf("%d/%d",n1,d1);
     if(n<0 && d>0)
     printf("-%d/%d",n1,d1);
