int find(int m,int i)
{
    int l,r,mid;
    l = 0;
    r = player[i].t-1;
    while(l <= r)
    {
        mid = (l + r) >> 1;
        if(m == player[i].a[mid])
            return 0;
        if(m < player[i].a[mid])
            r = mid - 1;
        else
            l = mid + 1;
    }
