    if (u) x -= row[0][i][u - 1];
    if (x) return false;

    u = i - len + 1, v = i + len - 1, x = col[0][v][j];
    if (u) x -= col[0][u - 1][j];
    if (x) return false;
    return true;
}

bool check2(int i, int j, int len){
