#include <stdio.h>
#include <stdlib.h>

int binsearch(int *arr, int len, int elem) {
	int start = 0, end = len - 1;
	int mid = (start + end) / 2; 
	while (start <= end && (arr[mid] != elem)) {
		if (elem > arr[mid])
			start = mid + 1;		
		else
			end = mid - 1;				
		mid = (start + end) / 2;		
	}
	if (elem <= arr[mid])
		return mid;
	else
		return mid + 1;
}

