{
    SieveOfEratosthenes();
    int Ans = -1, p, q, i;
    long long pi = 0, rub = 0;
    scanf("%d %d", &p, &q);
    for(i = 1; i < MAXN; ++i) {
        if(!NotPrime[i]) {
            ++pi;
        }
        if(IsPalindromic(i)) {
            ++rub;
        }
        if(q * pi <= p * rub) {
            Ans = i;
        }
    }
    if(Ans == -1) {
        puts("Palindromic tree is better than splay tree");
        return 0;
    }
    printf("%d\n", Ans);
    return 0;
}

