///selection sort

void mySort(int ins,int A[ins])
{
    int i,min,j,temp;
    for(i=0;i<ins-1;i++)
    {
        min = i;
        for(j=i+1;j<ins;j++)
        {
            if(A[min]>A[j])
            {
                min = j;
            }

        }
        ///swap
        temp = A[min];
        A[min] = A[i];
        A[i] = temp;
    }
}

