short flag[1010][1010];
short check(int lim)
{
    int i,j,k,cnt,tmp[1010];
    memset(flag,0,sizeof(flag));
    for(i=1;i<=n;i++)
    {
        cnt = 0;
        for(j=1;j<=m;j++) if(map[i][j]>=lim) tmp[++cnt] = j;
        for(j=1;j<=cnt;j++) for(k=j+1;k<=cnt;k++)
        {
            if(!flag[tmp[j]][tmp[k]]) flag[tmp[j]][tmp[k]] = 1;
            else return 1;
        }
    }
    return 0;
}
