  for(i = comienzo; i < fin; i++){
     for(j = i + 1; j < fin; j++){
         if(*(pointer+j) < *(pointer+i)){
             temp = *(pointer+j);
             *(pointer+j) = *(pointer+i);
             *(pointer+i) = temp;
         }
     }
  }
}

