void add ( char * mas , struct tag ** head , struct tag ** tail ) {

	register int i;
	struct tag * prev = ( struct tag * ) malloc ( sizeof ( struct tag ) );
	for ( i = 0 ; i < strlen ( mas ) + 1 ; ++i ) {
		prev -> str [ i ] = mas [ i ]; 
	}

	if ( ( * head ) == NULL ) {
		( * head ) = prev;
		( * head ) -> back = NULL;
	}
	else {
		prev -> back = ( * tail );
		( * tail ) -> next = prev;	
	}

	( * tail ) = prev;
	( * tail ) -> next = NULL;

}

void my_delete ( struct tag ** head , struct tag ** tail ) {
	if ( ( * head ) == ( * tail ) ) {
		( * head ) = NULL;
		( * tail ) = NULL;

	}
	else {
		( * tail ) = ( * tail ) -> back;
		( * tail ) -> next = NULL;		
	}
}

