typedef long long LL;

int A[100000];

int F(int x)
{
    int res;
    if(x==1)
    {
        return 1;
    }
    res=0;
    while(x!=1)
    {
        if(x&1)
        {
            ++res;
        }
        x/=2;
    }
    return res+1;
}

