void switch_to_yyyymmdd(char **records, int len)
{
  int i, j;
  char tmp[11], rev_tmp[11];
  for (i = 0; i < len; i++)
    {
      strcpy(tmp,records[i]);
      for (j =  0; j < 4; j++)
	rev_tmp[j] = tmp[6+j];
      rev_tmp[4] = '-';
      for (j = 5; j < 7; j++)
	rev_tmp[j] = tmp[j-2];
      rev_tmp[7] = '-';
      for (j = 8; j < 10; j++)
	rev_tmp[j] = tmp[j - 8];
      rev_tmp[10] = '\0';
      strcpy(records[i],rev_tmp);
    }
}

