int match(char *s, char *p) {
	// printf("s = %s p = %s\n", s, p);

	int i, k, n, l[100000];
	l[0] = 0; k = 0; n = strlen(p);
	for (i = 1; i < n; i++) {
		while (k > 0 && p[k] != p[i])
			k = l[k-1];
		if (p[k] == p[i])
			k++;
		l[i] = k;
		// printf("i = %d -> %d\n", i+1, k);
	}

	k = 0; 
	int m = strlen(s);
	for (i = 0; i < m; i++) {
		while (k > 0 && p[k] != s[i])
			k = l[k-1];
		if (p[k] == s[i])
			k++;

		// printf("i = %d -> %d\n", i+1, k);

		if (k == n)
			return n;
	}

	return k;
}

