typedef struct pt_s {
        int     x;
        int     y;
	char	fl;
} pt_t;
pt_t    pts[100010];
int	spc[100010];
pt_t	out[100010];

int comp (const void *a, const void *b)
{
        pt_t     *x = (pt_t *)a;
        pt_t     *y = (pt_t *)b;

	int	dx = x->y - x->x;
	int	dy = y->y - y->x;

	if (dx == dy) {
		if ((x->x < y->x) || (x->y < y->y)) {
			return -1;
		} 
		return 1;
	}
	return dx-dy;
}

int bs (int end, ll tgt)
{
        int mid;
	int st = 0;

        while (st <= end) {
                int tmp;

                mid = (st+end)/2;
                tmp = pts[mid].y-pts[mid].x;

                if (tmp < tgt) {
                        st = mid+1;
                } else if (tmp > tgt) {
                        end = mid - 1;
                } else {
                        if (pts[mid].fl) {
                                st = mid+1;
                        } else {
                                end = mid-1;
                        }
                }
        }
        return st;
}


