				tree[b][0]=tree[b+1][0];
				tree[b][1]=tree[b+1][1];
				tree[b+1][0]=swap[0];
				tree[b+1][1]=swap[1];
			}
		}
	}
	if(pos>neg)
		way=1;
	else
		way=0;
	while(1){
		if(way==1){
			if(tree[n-1][1]==0)
				break;
			for(a=0;a<=n-1;a++){
				if(tree[a][0]>0&&tree[a][1]!=0){
					apple=apple+tree[a][1];
