long tot1,tot2,total=0,z[5000005]={0},hash[20000005]={0},last[20000005]={0},ans1,ans2;
long work1(long count,long k)
{
	long o=count/k,tot=0,sum=0,i,j;
	for(i=2;i<=o;i++)
	{
		if(hash[i]==0)
		{
			z[++tot]=i;
			last[i]=i;
		}
		for(j=1;j<=tot && z[j]*i<=o;j++)
		{
			hash[z[j]*i]=1;
			last[z[j]*i]=z[j];
			if(i%z[j]==0)
				break;
		}
	}
	for(i=2;i<=o;i++)
		if(last[i]>=k)
			sum++;
	if(count>=k)
		sum++;
	return sum;
}
void dfs(long k,long p,long long u)
{
	if(u>gmax(tot1,tot2))
		return ;
	if(k<=total)
	{
		dfs(k+1,p,u);
		dfs(k+1,p+1,u*z[k]);
	}
	else if(p)
	{
		if(p%2)
		{
			ans1-=tot1/u;
			ans2-=tot2/u;
		}
		else
		{
			ans1+=tot1/u;
			ans2+=tot2/u;
		}
	}
}
