void add(int i, int size ){
    int j = 0;

    while(numbers[i] != 0){
            for(j = 0; j < size; j++){
                numbers[j]++;
                if(numbers[j] == 10)
                    numbers[j] = 0;
            }    
    }

}

void move(int i, int size){
    int j = 0;
    int first_number = 0;
    while(i > 0){
        for(j = 0; j < size; j++){
            if(j == 0){
                first_number = numbers[j];
                numbers[j] = numbers[j + 1];
            } else if (j == size - 1){
                numbers[j] = first_number;
            } else {
                numbers[j] = numbers[j + 1];
            }
        }    
        i--;
    }
}

void set(int size){
    int i = 0;
    for(i = 0; i < size; i++){
        numbers[i] = (int) temp[i] - 48;
    }
}

