int sort(int s[],int num){
    int i,j,temp;
    for(i=1;i<num;i++){
        for(j=i-1;j>=0;j--){
            if((s[j]<s[j+1])){
                temp=s[j];
                s[j]=s[j+1];
                s[j+1]=temp;
            }
        }
    }
    return 0;
}
