int isPrime(int num){

    int i ;
    if (num==1){
        return 0;
    }
    for (i=sqrt(num);i>1;i--)
        if (num%i==0)
            return 0;
    return 1;

}

int printPrimes(int A[],int n){

    int i=0 , j=2 , z=0;
    while (j<n){

        if(isPrime(j)==1){
            A[z]=j;
            z++;
            i++;
        }
        j++;

    }
    return z ;
}


